const oas = [];

function addUnidad(nivel, asignatura, unidad, nombreUnidad, lista) {
    for (const [codigo, eje, categoria, descripcion, indicadores] of lista) {
        oas.push({
            nivel,
            asignatura,
            unidad,
            nombre_unidad: nombreUnidad,
            eje,
            codigo,
            categoria,
            descripcion,
            indicadores
        });
    }
}

